INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('9b2f2f7c-3f21-48c8-ac36-15300b41f307', '21feff02-016d-46e2-bb9d-c27495133b1b', '31. óra: A törtek szorzását alkalmazó feladatok megoldása', 'Törtrész kiszámítása és szöveges feladatok megoldása szorzással.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "87ec00db-6622-4748-a3bd-0b5864d37892", "text": "Mennyi 60-nak a 3/4 része? (60 * 3/4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "45"}, {"id": "4543cabb-cce2-4937-b9c0-39d24361b47c", "text": "Mennyi 100-nak az 1/5 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "1099e515-d307-44f7-8e94-2a2b29f538ca", "text": "Egy 24 szeletes tortának megették az 1/3-át. Hány szeletet ettek meg?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}, {"id": "3052a9ab-ca95-4667-8701-fd0b148b4158", "text": "Egy 24 szeletes tortának megették az 1/3-át. Hány szelet maradt?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "16"}, {"id": "79adda11-c415-49bf-bd26-703af56670d9", "text": "Egy szám törtrészének kiszámításához a számot megszorozzuk a törttel.", "type": "true-false", "options": [{"id": "5ffff406-f6d9-48f2-9612-d81aab4b0c51", "text": "Igaz", "isCorrect": true}, {"id": "f20a0ebe-0619-4568-b5f1-c1a380bba856", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "cca6b598-514b-456c-994d-4722acf4c9ee", "text": "Mennyi 50-nek a 2/5 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "24f8fcfc-6092-484d-b6cf-05a4ca296a1d", "text": "Mennyi 1/2 óra percekben? (60 * 1/2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('e0d227ae-9edb-47de-afe9-4852ebdafb8b', '21feff02-016d-46e2-bb9d-c27495133b1b', '32. óra: Osztás törttel', 'Törttel való osztás szabálya: szorzás a reciprokával.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "70d8b2ba-38a3-42e0-bf56-1729dff02804", "text": "Hogyan osztunk törttel?", "type": "multiple-choice", "options": [{"id": "455bc1c6-3fa2-48cd-a38b-8b5876c05975", "text": "Az osztandót megszorozzuk az osztó reciprokával", "isCorrect": true}, {"id": "af163133-ac9f-4237-980c-51f5aecd4411", "text": "Az osztandót elosztjuk a nevezővel", "isCorrect": false}, {"id": "57d02429-428d-474a-ba32-cd9b0a2b2f5c", "text": "Mindig 1-et kapunk", "isCorrect": false}, {"id": "2afe0673-4435-4807-a337-bd501076bc1d", "text": "A számlálókat elosztjuk egymással", "isCorrect": false}], "timeLimit": 15}, {"id": "c29823f5-01dd-4d54-8bac-325ad3c5f3c7", "text": "Mennyi 2/3 : 4/5? (2/3 * 5/4)", "type": "multiple-choice", "options": [{"id": "1018f9f7-3d93-4308-8e28-4a97f7324e6e", "text": "10/12 (azaz 5/6)", "isCorrect": true}, {"id": "51f923fc-4837-4f68-bca6-7f334df0abc1", "text": "8/15", "isCorrect": false}, {"id": "8124b836-e570-4df5-b59e-3fc962da1811", "text": "6/8", "isCorrect": false}, {"id": "8f835545-2d61-4a8d-a901-075702fd7051", "text": "15/8", "isCorrect": false}], "timeLimit": 15}, {"id": "90cac276-4782-498e-a6df-9c2849e2466c", "text": "Mennyi 1/2 : 1/2?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "344a13d1-4a80-48cb-9ac0-a7854954eab9", "text": "Ha egy számot 1/2-del osztunk, az eredmény megegyezik a szám 2-vel való szorzatával.", "type": "true-false", "options": [{"id": "87104724-3f82-47a5-9d6f-aca35aeafcca", "text": "Igaz ( : 1/2 = * 2)", "isCorrect": true}, {"id": "da5e4808-dedb-4fd4-ae03-537b90af5213", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "fc9c11be-f9ed-4ee9-98bc-7667f193cb6c", "text": "Mennyi 6 : 1/3? (6 * 3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "18"}, {"id": "6648bbe6-36b2-4a7a-9ab8-853de2032f18", "text": "Törttel való osztáskor az osztandó nem változik, csak az osztót fordítjuk meg.", "type": "true-false", "options": [{"id": "f8559384-bd18-493e-9c03-bf2c6d9334df", "text": "Igaz", "isCorrect": true}, {"id": "db846db4-2d9d-48e2-ad65-2e7fce3f27e6", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "72ee85ad-56dc-4d3c-8119-bb5e161ba000", "text": "Mennyi 3/4 : 3/4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('6f989e20-d633-4d3e-805d-50c7ac1cfd63', '21feff02-016d-46e2-bb9d-c27495133b1b', '33. óra: Hétköznapi problémák megoldása törtek osztásának felhasználásával', 'Szöveges feladatok mérésekkel, átdarabolásokkal, törtek osztásával.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "15bd18ce-46d7-41e6-a6f6-0010f90cd7aa", "text": "Hány 1/4 literes pohár tölthető meg 3 liter almaléből? (3 : 1/4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}, {"id": "538f0ffd-fd41-48f3-89b7-b8b4a971ed02", "text": "Hány 1/2 kg-os csomag képezhető 5 kg cukorból?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "fe910cf9-018b-4774-9eb0-3454fd60361c", "text": "Egy 6 méteres szalagból 3/4 méteres darabokat vágunk. Hány darabot kapunk? (6 : 3/4 = 6 * 4/3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}, {"id": "7ad505e2-61a5-4d66-b50b-83b0e8d31ee9", "text": "Törtek osztásakor az eredmény lehet nagyobb az eredeti osztandónál, ha az osztó 1-nél kisebb tört.", "type": "true-false", "options": [{"id": "579a24bb-6180-4902-bbfe-5cd98aca8503", "text": "Igaz", "isCorrect": true}, {"id": "931084c3-9c83-444f-b17a-efb7cb355d7c", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "9fffc0b8-4702-40b3-a2ac-c90150e8b017", "text": "Hány 1/5 méteres darab vágható ki 2 méter anyagból?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "19dece43-9252-403b-91b7-24cb06cb59c9", "text": "A szöveges feladatoknál az adatok lejegyzése és a mértékegységek egyeztetése elengedhetetlen.", "type": "true-false", "options": [{"id": "0966c54a-1616-49dd-8821-edc1f103422b", "text": "Igaz", "isCorrect": true}, {"id": "0a9aa358-1e41-48c8-a102-8e28fa404a67", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "dd9ea44c-aa3d-454c-bdc5-20b2f19a1ca2", "text": "Mennyi 4 : 2/3? (4 * 3/2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('a09fce87-966b-463e-8a52-0b9e07de4ba8', '21feff02-016d-46e2-bb9d-c27495133b1b', '34. óra: Gyakorlóóra', 'A törtek szorzásának és osztásának rögzítése, feladatok gyakorlása.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "3d767283-5386-4c9f-a928-9136b5dbab6b", "text": "Mennyi 3/5 * 5/3?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "82709828-10ef-4455-89e7-56a57fd7b093", "text": "Mennyi 4/7 : 2/7? (4/7 * 7/2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "137e8886-d6bf-442a-99eb-c6aeae0a2079", "text": "Melyik állítás igaz?", "type": "multiple-choice", "options": [{"id": "81354585-f2b7-4201-9beb-9c78f149628a", "text": "Két 1-nél kisebb pozitív tört szorzata kisebb mindkét tényezőnél", "isCorrect": true}, {"id": "8a46e066-4ffc-4043-bb75-adf1d0dc83ec", "text": "A szorzat mindig nagyobb a tényezőknél", "isCorrect": false}, {"id": "baff6970-a264-43e5-8976-47ab8e9526d2", "text": "Az osztás mindig kisebb számot ad", "isCorrect": false}, {"id": "dbda6a8b-102c-4872-9edb-6d387949bd8f", "text": "Nincs reciproka a 4/5-nek", "isCorrect": false}], "timeLimit": 15}, {"id": "adfcdb91-5033-457f-a625-38eaafd28ce0", "text": "Mennyi 5/6 * 12? (5 * 2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "c3b1afef-df35-4a3c-897a-e2f2ded16395", "text": "A 2/3 osztva 1/3-dal 2-t ad.", "type": "true-false", "options": [{"id": "f0541c72-54c6-406e-ad04-69ead1031878", "text": "Igaz", "isCorrect": true}, {"id": "1425a413-160c-46cd-8847-67f94a336448", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "6bcddb4a-9da3-4e1a-9ec4-763848562819", "text": "Mennyi 3/8 : 3/8?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "1dff6a1d-a5d6-4561-8c8d-81f04ae63880", "text": "Mennyi 1/4 * 4/5?", "type": "multiple-choice", "options": [{"id": "07bbf339-920c-4986-8609-836e407a3a72", "text": "1/5", "isCorrect": true}, {"id": "b0860c74-60e5-4a5f-9611-7c9be19b2820", "text": "4/20", "isCorrect": false}, {"id": "d403d69a-5af4-4e89-9151-76e8a3bdb938", "text": "1/20", "isCorrect": false}, {"id": "a3fc40d4-7b2c-4f58-bec9-268a559e3080", "text": "4/9", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('a1a7cfe9-1397-4700-97d8-4a076666c4e9', '21feff02-016d-46e2-bb9d-c27495133b1b', '35. óra: Számonkérés', 'Számonkérés a közönséges törtek műveleteiből (10 kérdés).', 'Matematika', '6. osztály', 'Törtek', '[{"id": "47730cf3-5e34-4f3c-89b4-2a917cf33fa0", "text": "1. Mennyi 2/5 + 1/5?", "type": "multiple-choice", "options": [{"id": "e8b26877-303f-4dee-a531-d5c8e6a92aab", "text": "3/5", "isCorrect": true}, {"id": "fa05c399-4a49-452d-a8f6-e22d23a248f2", "text": "3/10", "isCorrect": false}, {"id": "885aa67e-000e-46cb-89ce-5530ce76f8e1", "text": "2/10", "isCorrect": false}, {"id": "9acf73f0-c21c-499c-bf76-78c986e5ca50", "text": "1/5", "isCorrect": false}], "timeLimit": 15}, {"id": "76c1c7e4-7036-4d78-9d72-aef2ecf23ffb", "text": "2. Mennyi 3/4 - 1/2? (3/4 - 2/4)", "type": "multiple-choice", "options": [{"id": "6cff9842-d467-4309-8de0-76f59020203b", "text": "1/4", "isCorrect": true}, {"id": "e64b2bf9-8b41-488a-9b6a-35d3fe164488", "text": "2/2", "isCorrect": false}, {"id": "9df91ac2-495b-4bcd-8308-7a6a84203f65", "text": "1/2", "isCorrect": false}, {"id": "ed4d2598-a276-4f7f-a89c-d04d0e95f370", "text": "2/4", "isCorrect": false}], "timeLimit": 15}, {"id": "94a867fa-0b5e-42f4-aab1-f7397fbd7ba7", "text": "3. Mennyi 2/3 * 3/4?", "type": "multiple-choice", "options": [{"id": "a4373698-a1a8-4e34-8248-1830f9c2465f", "text": "6/12 (azaz 1/2)", "isCorrect": true}, {"id": "838b3194-7047-45fc-899a-c48f57235aa7", "text": "5/7", "isCorrect": false}, {"id": "a95f0ae0-ec0d-431e-8449-522dbb24e81d", "text": "6/7", "isCorrect": false}, {"id": "4c2d207e-8f78-4df7-b21f-1f755cdca87f", "text": "2/4", "isCorrect": false}], "timeLimit": 15}, {"id": "433f84bd-eae9-42ed-9a0a-45a4ac50f374", "text": "4. Mennyi 1/2 : 1/4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "18f8c589-d5fd-40e0-8647-160154ca56af", "text": "5. Mi a 7/8 reciproka?", "type": "multiple-choice", "options": [{"id": "f889d44d-d580-4c5b-87c2-3f8b71d83714", "text": "8/7", "isCorrect": true}, {"id": "a5575223-3bcc-499b-8a79-dd7392465931", "text": "-7/8", "isCorrect": false}, {"id": "22ba9f8d-c6a5-44cb-a873-2e89419a15c4", "text": "1/7", "isCorrect": false}, {"id": "a8cd62b7-1e1a-4199-8ef8-59dbf23d22df", "text": "7/8", "isCorrect": false}], "timeLimit": 15}, {"id": "bd01058f-3da3-4a26-8a13-b9b30a7aec30", "text": "6. Mennyi 40-nek a 3/5 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "24"}, {"id": "59e7648a-f3ef-4b78-b725-3431e8670659", "text": "7. Egy szám és reciproka szorzata 1.", "type": "true-false", "options": [{"id": "a26b602f-2c22-4636-b923-5d1a75e42872", "text": "Igaz", "isCorrect": true}, {"id": "b0e97889-1a06-4f7e-bcf0-364e907deac4", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "980ab08e-5544-4ee3-813a-caacba6840e4", "text": "8. Mennyi 5 : 1/2?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "3c3a27bd-9b96-498e-bbeb-1de2b4f9eba2", "text": "9. A törtek szorzásakor a számlálót a számlálóval, a nevezőt a nevezővel szorozzuk.", "type": "true-false", "options": [{"id": "5beeae02-31f9-4f8e-be04-c80b154b7f61", "text": "Igaz", "isCorrect": true}, {"id": "9f7c6258-278b-4249-972d-17c47ea43ad3", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "9c88f010-c83f-4667-a19f-9f0c21f090aa", "text": "10. Hány negyedből áll 3 egész?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('65e04b1e-8a12-4074-8aa5-072d62f9a1bf', '21feff02-016d-46e2-bb9d-c27495133b1b', '36. óra: Matematikai játékok', 'Matematikai társasjátékok, stratégiák törtekkel, csoport- és páros munka.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "b870e489-88df-4398-b399-ec989927de49", "text": "Melyik állítás igaz a matematikai társasjátékokról?", "type": "multiple-choice", "options": [{"id": "fc99de56-fbbc-42bb-be30-d925f03cedfe", "text": "Fejlesztik a számolási gyorsaságot és a logikai stratégiát", "isCorrect": true}, {"id": "493c04c0-d8a9-47fd-92fb-89bc813c7af3", "text": "Nincs közük a matematikához", "isCorrect": false}, {"id": "6ba20ea9-4b08-4d79-9db9-6bcf9be99e38", "text": "Kizárólag szerencse kell hozzájuk", "isCorrect": false}, {"id": "501e0127-f72d-4bdf-a5ff-7a54af885947", "text": "Tiltható az együttműködés", "isCorrect": false}], "timeLimit": 15}, {"id": "36fda180-00eb-4b02-b4bc-2597a8ce514e", "text": "A tört domino játékban az egyenlő értékű törteket illesztjük össze.", "type": "true-false", "options": [{"id": "fd483b4c-f9ef-48be-92e1-2bcb24c76900", "text": "Igaz", "isCorrect": true}, {"id": "6e699e03-052d-4677-8c72-b74a8af35c11", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "64ce0177-d55c-4731-ae4a-142a53efbd60", "text": "Melyik tört felel meg a 0,5 tizedes törtnek?", "type": "multiple-choice", "options": [{"id": "a883c5bf-7bb2-4231-873d-ccc01876a0ea", "text": "1/2", "isCorrect": true}, {"id": "cb645475-fbb4-44ed-9bba-e68def9b8219", "text": "1/5", "isCorrect": false}, {"id": "58486b6f-b1ae-4b48-aa4d-0490d2036a9d", "text": "2/5", "isCorrect": false}, {"id": "c38f6e7c-bff6-41fd-a141-3f89ad07bede", "text": "5/2", "isCorrect": false}], "timeLimit": 15}, {"id": "45019589-fb9f-4fd7-b55c-4452c6bda13c", "text": "Melyik tört felel meg a 0,25-nek?", "type": "multiple-choice", "options": [{"id": "4c484c0d-6b77-48fd-8ea3-0b1857723e9b", "text": "1/4", "isCorrect": true}, {"id": "44755b09-ba54-43dd-b249-55eaaea2d38d", "text": "1/2", "isCorrect": false}, {"id": "c3cc52e0-e889-48c6-9aa7-764d757941de", "text": "2/5", "isCorrect": false}, {"id": "507a726c-52a1-461f-885e-aafb8de8a81e", "text": "3/4", "isCorrect": false}], "timeLimit": 15}, {"id": "949aaf9a-f0b2-4e74-a805-3a06bde57218", "text": "A 3/4 tizedes tört alakja 0,75.", "type": "true-false", "options": [{"id": "bfeba7d7-4538-4756-8215-252dd3a3196e", "text": "Igaz", "isCorrect": true}, {"id": "7839bc19-69fc-4d60-8f30-b2e3516f1280", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "5f946f64-c40a-44f8-a220-ab6a951ff7a2", "text": "Mennyi 0,2 közönséges tört alakban legegyszerűbb formában?", "type": "multiple-choice", "options": [{"id": "74050798-c3d4-4172-b2a9-946080b26391", "text": "1/5", "isCorrect": true}, {"id": "dd935252-fae8-4dc0-a091-f728920d14fd", "text": "2/10", "isCorrect": false}, {"id": "957ac72a-4a69-48da-b402-318067591833", "text": "1/2", "isCorrect": false}, {"id": "59386502-e5bb-4f12-825b-b2a553284376", "text": "2/5", "isCorrect": false}], "timeLimit": 15}, {"id": "8d63d2ff-d935-4336-92d5-00e67820bc64", "text": "A tört-bingó játékban a válaszok gyors és pontos kiszámítása a nyerő stratégia.", "type": "true-false", "options": [{"id": "495671cb-bfed-484a-b2c8-5ea5bedb8aaa", "text": "Igaz", "isCorrect": true}, {"id": "441ca6ea-f516-45c5-af43-c08bc9521c54", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('1788e7b2-8e3e-4328-8a19-4feed339e6c0', '21feff02-016d-46e2-bb9d-c27495133b1b', '37. óra: Mit tanultunk a tizedes törtekről?', 'Tizedes törtek helyi értékei, összeadása és kivonása.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "015aa7b1-224e-4568-a7ed-86fa41ae1277", "text": "Mi a tizedesvessző utáni első helyi érték neve?", "type": "multiple-choice", "options": [{"id": "d01c9a5f-449b-402e-a3b9-6fa6a95789f4", "text": "Tizedek", "isCorrect": true}, {"id": "f1fb9b88-54a8-4e31-98c5-bc3eaeb221ad", "text": "Századok", "isCorrect": false}, {"id": "01705681-0bff-40ed-b4d8-a5f11143705e", "text": "Ezredeket", "isCorrect": false}, {"id": "9a528b24-cd86-4caf-b1b0-f9be84a1a565", "text": "Egyesek", "isCorrect": false}], "timeLimit": 15}, {"id": "9e99ee43-f519-445a-80b8-13e9b0bb1a35", "text": "Mi a tizedesvessző utáni második helyi érték neve?", "type": "multiple-choice", "options": [{"id": "3ac2507c-6f61-4b92-b235-a2898f2020d9", "text": "Századok", "isCorrect": true}, {"id": "9d1a4048-5016-442c-9170-6f03e58e3ba8", "text": "Tizedek", "isCorrect": false}, {"id": "a4ff2f93-e907-4de2-96de-bbe99902d3ba", "text": "Ezredek", "isCorrect": false}, {"id": "a697e371-55f8-42a2-94af-f743e541300d", "text": "Tízesek", "isCorrect": false}], "timeLimit": 15}, {"id": "726c2423-7336-44b7-8c81-f62a59beb861", "text": "Mennyi 3,45 + 2,13?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5.58"}, {"id": "9617ef73-fb78-44b9-81df-c7da70601419", "text": "Mennyi 7,8 - 3,5?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4.3"}, {"id": "6abf6ac0-10bf-4044-b655-d492d881862a", "text": "Tizedes törtek írásbeli összeadásakor a tizedesvesszőknek egymás alá kell kerülniük.", "type": "true-false", "options": [{"id": "20e8c720-41cc-437e-b24d-f45e326dd7a2", "text": "Igaz", "isCorrect": true}, {"id": "2e91b6a1-ec29-48d0-b392-3596ce94690a", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "a199e909-ab18-4eef-8854-b8ace1eb7509", "text": "Mennyi 5,6 + 4,4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "0b728cd9-9524-43e5-9832-3ae80f00c190", "text": "Melyik szám nagyobb: 4,05 vagy 4,5?", "type": "multiple-choice", "options": [{"id": "a57d39ab-fd12-4489-8294-df004a29b80e", "text": "4,5 (mert 4,5 = 4,50)", "isCorrect": true}, {"id": "d7652340-0bc3-4c5f-ab92-a3dcafe360c3", "text": "4,05", "isCorrect": false}, {"id": "55f153ed-1f71-48ad-8afd-75846f8f1319", "text": "Egyenlőek", "isCorrect": false}, {"id": "8ad518ce-ec85-42c3-a54a-79103df7deb8", "text": "Nem eldönthető", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('ff494dc5-db1a-46b3-90f0-7110c49c2cef', '21feff02-016d-46e2-bb9d-c27495133b1b', '38. óra: Szorzás tizedes törttel', 'Tizedes tört szorzása egész számmal és tizedes törttel, vesszőhely meghatározása.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "4333ed91-800d-4ea4-bd17-68b353460b96", "text": "Hogyan határozzuk meg a tizedesjegyek számát két tizedes tört szorzatában?", "type": "multiple-choice", "options": [{"id": "0a705f3a-75ae-4b8a-b7a4-1d0acf5edc09", "text": "A tényezők tizedesjegyeinek számát összeadjuk", "isCorrect": true}, {"id": "d98074e7-2d61-4c12-b831-1a0d053b9038", "text": "A nagyobbik tényező tizedesjegyeit vesszük", "isCorrect": false}, {"id": "f6eb8469-8aee-4cf7-9bff-693d2a17b002", "text": "Mindig 1 tizedesjegy lesz", "isCorrect": false}, {"id": "869b4e38-419f-4124-aed0-20125b701a0a", "text": "Nem lesz tizedesjegy", "isCorrect": false}], "timeLimit": 15}, {"id": "642084a4-e2d1-49da-afeb-1d915f89ef36", "text": "Mennyi 0,3 * 0,2? (3*2 = 6, 2 tizedesjegy)", "type": "multiple-choice", "options": [{"id": "c34e0e29-bdad-4374-8a63-40d4da71e59a", "text": "0,06", "isCorrect": true}, {"id": "c42fb71f-d252-456a-a10a-14d1046677b8", "text": "0,6", "isCorrect": false}, {"id": "719b1ad9-1731-4ac3-9947-9c6f0af4af2f", "text": "6,0", "isCorrect": false}, {"id": "a1e4b417-d008-4067-82a4-052f1b6a54c7", "text": "0,006", "isCorrect": false}], "timeLimit": 15}, {"id": "7ee5f429-9ffa-43a6-a7c4-3f672e36a3c1", "text": "Mennyi 2,5 * 4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "328685a6-b390-4eb3-8c3e-e1d8d08b3a3c", "text": "Mennyi 1,2 * 0,5?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "0.6"}, {"id": "d67ac358-3d44-43e7-a3d9-5bb4de98eb0a", "text": "Ha egy tizedes törtet 10-zel szorzunk, a tizedesvessző egy hellyel jobbra lép.", "type": "true-false", "options": [{"id": "16b9c54d-028e-4b92-92dc-13198f15d386", "text": "Igaz", "isCorrect": true}, {"id": "fa879120-a4ba-4191-9b22-f6ac658d2b7b", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "59e62fd4-5451-403a-b9b1-f7a81ea77045", "text": "Mennyi 3,45 * 100?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "345"}, {"id": "f75cadb1-94ec-41be-a2fb-f19b3ec185e8", "text": "Mennyi 0,1 * 0,1?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "0.01"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('24cd2802-77c6-4166-905d-1ac8668636b5', '21feff02-016d-46e2-bb9d-c27495133b1b', '39. óra: Osztás tizedes törttel', 'Tizedes törttel való osztás szabálya, osztó egész számmá alakítása (bővítés 10-zel, 100-zal).', 'Matematika', '6. osztály', 'Törtek', '[{"id": "2a7d1356-fa5a-40be-bb03-f850b49344f6", "text": "Mit teszünk tizedes törttel való osztáskor először?", "type": "multiple-choice", "options": [{"id": "1971baec-abda-4828-870d-a97f12e0c1cb", "text": "Az osztandót és az osztót is megszorozzuk 10-zel/100-zal, hogy az osztó egész szám legyen", "isCorrect": true}, {"id": "274c643d-9baa-4061-b3c4-90088dda042a", "text": "Elhagyjuk a tizedesvesszőt az osztandóból", "isCorrect": false}, {"id": "887a034f-44e9-450f-a28e-b990e6799fc2", "text": "Kivonjuk az osztót az osztandóból", "isCorrect": false}, {"id": "e5efb01d-47a9-4344-9601-7c4548339bdb", "text": "Csak az osztót szorozzuk meg", "isCorrect": false}], "timeLimit": 15}, {"id": "e045f2c0-9c2d-41c6-a158-9b91bb2c7bb9", "text": "Mennyi 2,4 : 0,6? (24 : 6)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "ede5ddcb-bdf6-42f8-8960-bc0b0c9d0c1d", "text": "Mennyi 1,5 : 0,3? (15 : 3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "97aa64a8-9f07-4988-89fa-66bc224e39db", "text": "Ha egy tizedes törtet 10-zel osztunk, a tizedesvessző 1 hellyel balra lép.", "type": "true-false", "options": [{"id": "0b4f56fd-730f-4033-ab8b-6ad604ff9aee", "text": "Igaz", "isCorrect": true}, {"id": "576a8a1a-f1c9-4ec7-a7a9-cd895815c57f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "a6c3dd71-2c97-4634-a447-2b6771a614ff", "text": "Mennyi 45,6 : 10?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4.56"}, {"id": "9e5373c9-9a94-4eee-9412-1682e32e5664", "text": "Mennyi 3,6 : 0,1? (36 : 1)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "36"}, {"id": "366a79d1-49b7-409b-8781-7f61e177c48a", "text": "A tizedes törttel való osztást ellenőrizhetjük szorzással.", "type": "true-false", "options": [{"id": "909555df-609f-4319-a4db-27ddcf27ad0d", "text": "Igaz", "isCorrect": true}, {"id": "bfabaf31-dd7a-4b58-854a-2c0fc5a288f3", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('7d766d4c-edd8-496b-adf4-bdceefede50d', '21feff02-016d-46e2-bb9d-c27495133b1b', '40. óra: Hétköznapi problémák megoldása tizedes törtek szorzásának, osztásának felhasználásával', 'Vásárlási, mértékegységes és szöveges feladatok.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "ac6418ff-7d56-469a-a9d9-a443e558f5cf", "text": "1 kg sajt ára 3200 Ft. Mennyibe kerül 0,5 kg sajt? (3200 * 0,5)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1600"}, {"id": "53b11bf8-0569-44a2-a097-eda139941d17", "text": "Peti 3,5 kg almát vett 400 Ft/kg áron. Hány Ft-ot fizetett?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1400"}, {"id": "4e7d09aa-0a50-41b7-a73d-092cd7883e53", "text": "Egy 4,8 méteres lécet 4 egyenlő darabra vágunk. Hány méter egy darab?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1.2"}, {"id": "36329ad5-8e43-4609-8d47-219ea026cfaf", "text": "Ha 0,25 liter üdítő 150 Ft, akkor 1 liter üdítő (4 * 0,25) 600 Ft-ba kerül.", "type": "true-false", "options": [{"id": "32f177f5-9a37-4bb2-95bd-7a4f7909a885", "text": "Igaz", "isCorrect": true}, {"id": "a3bebac4-7c7f-447d-9386-4317fed5368f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "8c5f4a50-a48a-4210-b3c5-6aa71b12e754", "text": "Hány liter benzin fér a tankba 12000 Ft-ért, ha 1 liter benzin 600 Ft?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "5380b53b-6429-4064-a1e8-1880a1bd449b", "text": "A becslés segít ellenőrizni, hogy a tizedesvesszőt jó helyre tettük-e a végeredményben.", "type": "true-false", "options": [{"id": "3b4db5e1-385d-42d0-b417-fbccbeb4056f", "text": "Igaz", "isCorrect": true}, {"id": "11c24253-6517-49df-bd52-21861b538ad4", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "ff3f7c81-ab52-476c-8c2d-12271f71e464", "text": "Mennyi 1,5 kg narancs ára, ha 1 kg 800 Ft?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1200"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;